const trigger = $('On form submission').first();
const sourceFilename =
  trigger.json.file?.filename ||
  trigger.json.file?.[0]?.filename ||
  trigger.json.filename ||
  trigger.json['file.filename'] ||
  'unknown';

// Canonical schema header synonyms
const HEADER_SYNONYMS = {
  location:   ['location', 'store', 'branch', 'site', 'region'],
  sale_date:  ['sale_date', 'date', 'saledate', 'transaction_date', 'order_date'],
  sku:        ['sku', 'item', 'product_code', 'item_code', 'product'],
  quantity:   ['quantity', 'qty', 'units', 'count'],
  unit_price: ['unit_price', 'price', 'unitprice', 'price_per_unit'],
  total:      ['total', 'amount', 'line_total']
};

function normalizeHeader(raw) {
  const cleaned = String(raw).trim().toLowerCase().replace(/[\s_\-]+/g, '_');
  for (const [canonical, synonyms] of Object.entries(HEADER_SYNONYMS)) {
    if (synonyms.includes(cleaned)) return canonical;
  }
  return null;
}

const output = [];

for (const item of $input.all()) {
  const rawRow = item.json;
  const normalizedRow = {};

  for (const [rawHeader, value] of Object.entries(rawRow)) {
    const canonical = normalizeHeader(rawHeader);
    if (canonical) {
      normalizedRow[canonical] = value;
    }
  }

  output.push({
    json: {
      source_filename: sourceFilename,
      raw_row: JSON.stringify(rawRow),
      normalized_row: JSON.stringify(normalizedRow)
    }
  });
}

return output;

const CANONICAL_SCHEMA = {
  location:   { required: true,  type: 'string', enum: ['store_a', 'store_b', 'store_c'] },
  sale_date:  { required: true,  type: 'date' },
  sku:        { required: true,  type: 'string' },
  quantity:   { required: true,  type: 'number', min: 1, soft_max: 1000 },
  unit_price: { required: true,  type: 'number', min: 0.01 },
  total:      { required: false, type: 'number' }
};

function classifyRow(normalizedRow) {
  const reasons = [];

  for (const [field, spec] of Object.entries(CANONICAL_SCHEMA)) {
    const value = normalizedRow[field];

    // Required check
    if (spec.required && (value === undefined || value === null || value === '')) {
      reasons.push({ field, code: 'REQUIRED_MISSING', severity: 'ERROR' });
      continue;
    }
    if (value === undefined || value === null || value === '') continue;

    // Number type
    if (spec.type === 'number') {
      const n = Number(value);
      if (isNaN(n)) {
        reasons.push({ field, code: 'TYPE_MISMATCH', severity: 'ERROR' });
        continue;
      }
      normalizedRow[field] = n;

      if (spec.min !== undefined && n < spec.min) {
        reasons.push({ field, code: 'RANGE_VIOLATION', severity: 'ERROR' });
      }
      if (spec.soft_max !== undefined && n > spec.soft_max) {
        reasons.push({ field, code: 'SOFT_RANGE', severity: 'WARNING' });
      }
    }

    // Date type â€” handle Excel serial numbers
    if (spec.type === 'date') {
      const serial = Number(value);
      const isExcelSerial =
        (typeof value === 'number' || /^\d+$/.test(String(value))) &&
        serial >= 43000 && serial <= 50000;

      let d;
      if (isExcelSerial) {
        const excelEpoch = Date.UTC(1899, 11, 30);
        const ms = serial * 24 * 60 * 60 * 1000;
        d = new Date(excelEpoch + ms);
      } else {
        d = new Date(value);
      }

      if (isNaN(d.getTime())) {
        reasons.push({ field, code: 'TYPE_MISMATCH', severity: 'ERROR' });
        continue;
      }

      normalizedRow[field] = d.toISOString().slice(0, 10);

      if (d > new Date()) {
        reasons.push({ field, code: 'FUTURE_DATE', severity: 'WARNING' });
      }
    }

    // Enum check
    if (spec.enum && !spec.enum.includes(value)) {
      reasons.push({ field, code: 'ENUM_MISMATCH', severity: 'WARNING' });
    }
  }

  // Compute total if missing
  if (
    normalizedRow.total == null &&
    normalizedRow.quantity != null &&
    normalizedRow.unit_price != null
  ) {
    normalizedRow.total = +(normalizedRow.quantity * normalizedRow.unit_price).toFixed(2);
  }

  const hasError = reasons.some(r => r.severity === 'ERROR');
  const hasWarning = reasons.some(r => r.severity === 'WARNING');

  return {
    classification: hasError ? 'invalid' : (hasWarning ? 'suspicious' : 'valid'),
    reason: reasons.length ? JSON.stringify(reasons) : null
  };
}

const output = [];

for (const item of $input.all()) {
  const normalizedRow = JSON.parse(item.json.normalized_row);
  const { classification, reason } = classifyRow(normalizedRow);

  output.push({
    json: {
      source_filename: item.json.source_filename,
      raw_row: item.json.raw_row,
      normalized_row: JSON.stringify(normalizedRow),
      classification,
      reason
    }
  });
}

return output;

const allRows = $('Validate Rows').all();

const validCount = allRows.filter(r => r.json.classification === 'valid').length;
const suspiciousCount = allRows.filter(r => r.json.classification === 'suspicious').length;
const invalidCount = allRows.filter(r => r.json.classification === 'invalid').length;

const stagingRows = $('Write Staging Rows').all();
const importRunId = stagingRows.length > 0 ? stagingRows[0].json.import_run_id : null;

const sourceFilename = $('Normalize Headers').first().json.source_filename 
  || $('On form submission').first().json.file?.filename 
  || 'unknown';

return [{
  json: {
    import_run_id: importRunId,
    source_filename: sourceFilename,
    total_rows: allRows.length,
    valid_count: validCount,
    suspicious_count: suspiciousCount,
    invalid_count: invalidCount
  }
}];

