const firstRow = $('Validate Rows').first().json;
const sourceFilename = firstRow.source_filename || 'unknown';
const rows = $('Validate Rows').all();

// Escape single quotes for SQL string literals
function esc(s) {
  if (s === null || s === undefined) return '';
  return String(s).replace(/'/g, "''");
}

// Build the VALUES list
const valuesList = rows.map((item, idx) => {
  const r = item.json;
  const rawEscaped = esc(r.raw_row);
  const normEscaped = esc(r.normalized_row);
  const reasonEscaped = esc(r.reason || '');
  const classification = r.classification || 'invalid';

  return `(
    ${idx + 1},
    '${rawEscaped}'::jsonb,
    '${normEscaped}'::jsonb,
    '${classification}',
    NULLIF('${reasonEscaped}', '')
  )`;
}).join(',\n');

const sql = `
WITH new_run AS (
  INSERT INTO spreadsheet_import_runs (
    source_filename, total_rows, valid_count, suspicious_count, invalid_count, status, processed_at
  ) VALUES (
    '${esc(sourceFilename)}',
    ${rows.length},
    ${rows.filter(r => r.json.classification === 'valid').length},
    ${rows.filter(r => r.json.classification === 'suspicious').length},
    ${rows.filter(r => r.json.classification === 'invalid').length},
    'staged',
    NOW()
  )
  RETURNING id
)
INSERT INTO spreadsheet_staging (
  import_run_id,
  source_row_number,
  raw_row,
  normalized_row,
  classification,
  reason
)
SELECT
  new_run.id,
  v.source_row_number,
  v.raw_row,
  v.normalized_row,
  v.classification,
  v.reason
FROM new_run,
LATERAL (VALUES
${valuesList}
) AS v(source_row_number, raw_row, normalized_row, classification, reason)
RETURNING id, import_run_id;
`;

return [{ json: { sql } }];
